using System;using System.Linq;using System.Globalization;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
public sealed partial class SettingsWindow {
 ComboBox terminalFont,terminalSize,terminalLine,terminalSpacing,terminalCursor,terminalBuffer;CheckBox terminalBlink;TextBlock terminalPreview;
 ComboBox TerminalChoice(Panel parent,string title,string[] choices,string selected,bool editable=false){parent.Children.Add(Theme.Text(title,13,Theme.Muted));var combo=new ComboBox{ItemsSource=choices,SelectedItem=selected,IsEditable=editable,Text=selected,MinHeight=38,Margin=new Thickness(0,7,0,16)};parent.Children.Add(combo);return combo;}
 void BuildTerminalSettings(Panel parent){var value=(Result.Terminal??new TerminalPreferences()).Copy();var expander=new Expander{Header="终端外观与行为",IsExpanded=true,Foreground=Theme.Ink,Margin=new Thickness(0,8,0,20)};var body=new StackPanel{Margin=new Thickness(0,16,0,0)};expander.Content=body;parent.Children.Add(expander);var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());var left=new StackPanel{Margin=new Thickness(0,0,8,0)};var right=new StackPanel{Margin=new Thickness(8,0,0,0)};grid.Children.Add(left);Grid.SetColumn(right,1);grid.Children.Add(right);body.Children.Add(grid);
 terminalFont=TerminalChoice(left,"字体",new[]{value.FontFamily,"Cascadia Mono","Cascadia Code","Consolas","Courier New","Lucida Console"}.Distinct().ToArray(),value.FontFamily);terminalSize=TerminalChoice(right,"字号",new[]{10,12,13,14,15,16,18,20,22,24,28,32,value.FontSize}.Distinct().OrderBy(x=>x).Select(x=>x.ToString()).ToArray(),value.FontSize.ToString());terminalLine=TerminalChoice(left,"行高",new[]{1.0,1.1,1.2,1.35,1.5,1.65,1.8,value.LineHeight}.Distinct().OrderBy(x=>x).Select(x=>x.ToString("0.00",CultureInfo.InvariantCulture)).ToArray(),value.LineHeight.ToString("0.00",CultureInfo.InvariantCulture));terminalSpacing=TerminalChoice(right,"字符间距",new[]{0.0,.5,1,1.5,2,value.LetterSpacing}.Distinct().OrderBy(x=>x).Select(x=>x.ToString("0.0",CultureInfo.InvariantCulture)).ToArray(),value.LetterSpacing.ToString("0.0",CultureInfo.InvariantCulture));terminalCursor=TerminalChoice(left,"光标样式",new[]{"竖线","方块","下划线"},value.CursorStyle=="block"?"方块":value.CursorStyle=="underline"?"下划线":"竖线");terminalBuffer=TerminalChoice(right,"回滚记录（行）",new[]{500,1000,5000,10000,20000,50000,100000,value.Scrollback}.Distinct().OrderBy(x=>x).Select(x=>x.ToString()).ToArray(),value.Scrollback.ToString());terminalBlink=new CheckBox{Content="光标闪烁",IsChecked=value.CursorBlink,Margin=new Thickness(0,0,0,14)};body.Children.Add(terminalBlink);terminalPreview=Theme.Text("(base) user@aq-server:~$ python train.py\n训练日志 · Epoch 12 / 100   GPU 0",16,Theme.Ink);terminalPreview.TextWrapping=TextWrapping.Wrap;var preview=new Border{Background=Theme.TerminalBackground,Padding=new Thickness(16),CornerRadius=new CornerRadius(8),Child=terminalPreview};body.Children.Add(preview);terminalFont.SelectionChanged+=(s,e)=>PreviewTerminal();terminalFont.LostFocus+=(s,e)=>PreviewTerminal();terminalSize.SelectionChanged+=(s,e)=>PreviewTerminal();terminalLine.SelectionChanged+=(s,e)=>PreviewTerminal();PreviewTerminal();}
 void PreviewTerminal(){if(terminalPreview==null)return;string family=terminalFont.Text;if(terminalFont.SelectedItem!=null)family=terminalFont.SelectedItem.ToString();int size;if(!int.TryParse(terminalSize.SelectedItem as string,out size))size=16;double line;if(!double.TryParse(terminalLine.SelectedItem as string,NumberStyles.Float,CultureInfo.InvariantCulture,out line))line=1.35;try{terminalPreview.FontFamily=new FontFamily((string.IsNullOrWhiteSpace(family)?"Consolas":family)+", Consolas, Microsoft YaHei UI");}catch{}terminalPreview.FontSize=size;terminalPreview.LineHeight=size*line;}
 void CaptureTerminalSettings(){var p=new TerminalPreferences{FontFamily=terminalFont.SelectedItem as string,FontSize=int.Parse(terminalSize.SelectedItem as string),LineHeight=double.Parse(terminalLine.SelectedItem as string,CultureInfo.InvariantCulture),LetterSpacing=double.Parse(terminalSpacing.SelectedItem as string,CultureInfo.InvariantCulture),CursorStyle=terminalCursor.SelectedIndex==1?"block":terminalCursor.SelectedIndex==2?"underline":"bar",CursorBlink=terminalBlink.IsChecked==true,Scrollback=int.Parse(terminalBuffer.SelectedItem as string)};p.Normalize();Result.Terminal=p;}
}
